import type { EngineInterface as Engine, Register } from 'claude-code'

import { flashAction, isFocused, needsNotification, parseProbe, sessionUuid, ATTENTION_TYPES } from './attention'
import type { Probe } from './attention'

const FLASHING = { plugin: 'iterm-attention', key: 'flashing' } as const
const TICK_MS = 350
const GIVE_UP_MS = 30 * 60 * 1000

let stopFlash: (() => void) | undefined

function script($: Engine): string {
  return `${$.plugin.root}/hooks/iterm.applescript`
}

async function iterm($: Engine, uuid: string, action: string, bg?: string): Promise<Probe | undefined> {
  const argv = ['osascript', script($), uuid, action, ...(bg ? [bg] : [])]
  const { exitCode, stdout } = await $.process.run(argv, { timeoutMs: 5000 })
  return exitCode === 0 ? parseProbe(stdout) : undefined
}

async function notify($: Engine, uuid: string, message: string) {
  const focus = `osascript '${script($)}' ${uuid} focus`
  await $.process.run([
    'terminal-notifier',
    '-title', 'Claude Code',
    '-message', message || 'Claude needs your attention',
    '-group', `claude-attention-${uuid}`,
    '-execute', focus,
  ])
}

async function restore($: Engine) {
  const { value } = await $.state.get(FLASHING)
  if (!value) return
  await $.state.set(FLASHING, null)
  await iterm($, value.sessionId, 'off', value.bg).catch(() => undefined)
  await $.process.run(['terminal-notifier', '-remove', `claude-attention-${value.sessionId}`]).catch(() => undefined)
}

async function attend($: Engine, message: string) {
  if (stopFlash) return
  const uuid = sessionUuid(await $.env.get('ITERM_SESSION_ID'))
  if (!uuid) return

  const first = await iterm($, uuid, 'probe')
  if (!first || isFocused(first)) return

  let isStopped = false
  stopFlash = () => {
    isStopped = true
  }
  await $.state.set(FLASHING, { sessionId: uuid, bg: first.bg })
  if (needsNotification(first)) await notify($, uuid, message)

  void (async () => {
    const startedAt = await $.clock.now()
    let isLit = true
    let probe: Probe | undefined = first
    try {
      while (!isStopped && probe && !isFocused(probe)) {
        if ((await $.clock.now()) - startedAt > GIVE_UP_MS) break
        probe = await iterm($, uuid, flashAction(probe, isLit), first.bg)
        isLit = !isLit
        await $.clock.sleep(TICK_MS)
      }
    } finally {
      stopFlash = undefined
      await restore($)
    }
  })()
}

export const register: Register = on => {
  // a reload mid-flash leaves the colors changed: put them back
  on('session.start', ($, e, next) => {
    void restore($).catch(() => undefined)
    return next(e)
  })

  // observe only: the flash runs beside the engine, never in its way
  on('classic.Notification', ($, e, next) => {
    if (ATTENTION_TYPES.includes(e.notification_type)) void attend($, e.message).catch(() => undefined)
    return next(e)
  })

  on('classic.Stop', ($, e, next) => {
    void attend($, 'Claude finished and is waiting for you').catch(() => undefined)
    return next(e)
  })

  // the person answered (possibly from elsewhere): stop blinking
  on('prompt.submit', ($, e, next) => {
    stopFlash?.()
    return next(e)
  })
}

