// Pure decisions, kept apart from the hooks so tests can reach them.

export type Probe = {
  isFront: boolean
  isFrontWindow: boolean
  isTabCurrent: boolean
  isSessionCurrent: boolean
  tty: string
  bg: string
}

export type FlashAction = 'pane-on' | 'tab-on' | 'off'

export function parseProbe(out: string): Probe | undefined {
  const parts = out.trim().split('|')
  if (parts.length !== 6) return undefined
  const [front, win, tab, sess, tty = '', bg = ''] = parts
  return {
    isFront: front === 'true',
    isFrontWindow: win === 'true',
    isTabCurrent: tab === 'true',
    isSessionCurrent: sess === 'true',
    tty,
    bg,
  }
}

// Looking at it: iTerm in front, our window in front, our tab shown, our pane selected.
export function isFocused(p: Probe): boolean {
  return p.isFront && p.isFrontWindow && p.isTabCurrent && p.isSessionCurrent
}

// Away from iTerm, or in another iTerm window: only a notification can reach them.
export function needsNotification(p: Probe): boolean {
  return !p.isFront || !p.isFrontWindow
}

// Our tab is shown: blink the pane; otherwise blink the tab.
export function flashAction(p: Probe, isLit: boolean): FlashAction {
  if (!isLit) return 'off'
  return p.isTabCurrent ? 'pane-on' : 'tab-on'
}

// The session's uuid from ITERM_SESSION_ID ("w0t3p0:481DDD8B-...").
export function sessionUuid(itermSessionId: string | undefined): string | undefined {
  const uuid = itermSessionId?.split(':')[1]
  return uuid ? uuid : undefined
}

export const ATTENTION_TYPES = ['permission_prompt', 'idle_prompt', 'elicitation_dialog']

